#Requires -Version 5.1
<#
.SYNOPSIS
  Prints governance/debt-report.json: grouped metrics, full table, optional deltas vs governance-previous/debt-report.json.
#>
$ErrorActionPreference = 'Stop'
$here = $PSScriptRoot
$repoRoot = Split-Path -Parent $here
$reportPath = Join-Path $here 'debt-report.json'
$prevPath = Join-Path $repoRoot 'governance-previous\debt-report.json'

if (-not (Test-Path $reportPath)) {
    Write-Host "No debt-report.json at $reportPath (run scan-debt.ps1 first)." -ForegroundColor Yellow
    exit 0
}

$j = Get-Content $reportPath -Raw -Encoding UTF8 | ConvertFrom-Json

function Get-ReportValue($name) {
    if (-not ($j.PSObject.Properties.Name -contains $name)) { return $null }
    return $j.$name
}

Write-Host '=== Governance metrics by area (this run) ===' -ForegroundColor Cyan

Write-Host "`n[Concurrency]" -ForegroundColor Yellow
Write-Host ("  {0,-45} {1}" -f 'conflictProblemDetailsCount', (Get-ReportValue 'conflictProblemDetailsCount'))
Write-Host ("  {0,-45} {1}" -f 'concurrencyExceptionHandlingCount', (Get-ReportValue 'concurrencyExceptionHandlingCount'))
Write-Host ("  {0,-45} {1}" -f 'concurrencyReadyEntityCount', (Get-ReportValue 'concurrencyReadyEntityCount'))
