Write-Host "`n=== All debt-report fields (sorted) ===" -ForegroundColor Cyan
$j.PSObject.Properties.Name | Sort-Object | ForEach-Object {
    $v = $j.$_
    Write-Host ("  {0,-40} {1}" -f $_, $v)
}

if (Test-Path $prevPath) {
    Write-Host "`n=== Debt metric deltas (current - previous artifact) ===" -ForegroundColor Cyan
    $prev = Get-Content $prevPath -Raw -Encoding UTF8 | ConvertFrom-Json
    $keys = @($j.PSObject.Properties.Name + $prev.PSObject.Properties.Name) | Sort-Object -Unique
    $any = $false
    foreach ($k in $keys) {
        if ($k.StartsWith('_') -or $k -eq 'lastGeneratedUtc') { continue }
        try {
            $a = [double]$j.$k
            $b = [double]$prev.$k
        }
        catch {
            continue
        }
        $d = $a - $b
        if ($d -ne 0) {
            Write-Host ("  {0}: {1} -> {2} (delta {3:+g})" -f $k, $b, $a, $d)
            $any = $true
        }
    }
    if (-not $any) {
        Write-Host '  (no numeric deltas vs previous artifact)' -ForegroundColor DarkGray
    }
}
else {
    Write-Host "`nINFO: No governance-previous/debt-report.json; skipping delta block (typical on main or first run)." -ForegroundColor DarkGray
}
